Ext._define('judicial.tac.DocumentGrid', {
    extend: 'core.RestfulGrid',

    restWindow: 'judicial.tac.DocumentWindow',

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: 'Descricao', dataIndex: 'unicode', id: 'autoExpandColumn', hidden: true},
                    {header: '',dataIndex: 'icons',width: 30,menuDisabled: true,renderer: core.rendererIconGrid},
                    {header: 'Titulo', dataIndex: 'title', width: 200},
                    {header: 'Por', dataIndex: 'created_by_unicode', width: 150},
                    {header: 'Em', dataIndex: 'created_at', width: 150, renderer: Ext.util.Format.dateRenderer('d/m/Y H:i')},
                ]
            );

        return this._columnModel;
    },

    actionAccept: function(param){
        var selected = this.getSelectionModel().getSelected();
        var rest = Ext._create('judicial.tac.DocumentRestful', {});
        var mask = new Ext.LoadMask(this.getEl(), {msg: 'Aplicando alterações...'});

        if (selected){
            mask.show();
            rest.doRequest(
                rest.getRoute('action_accept', false, 'POST', {
                    params: {
                        pk: selected.get('pk'),
                        acao: param
                    },
                    scope: this,
                    callback: function() {
                        mask.hide();
                        mask = null;
                    },
                    success: function(xhr) {
                        this.getStore().reload();
                    },
                    failure: function(xhr) {
                        Ext.Msg.show({
                            title: 'Erro',
                            icon: Ext.Msg.ERROR,
                            buttons: Ext.Msg.OK,
                            msg: 'Não consegui aplicar a ação'
                        });
                    }
                })
            );
        }else{
            Ext.Msg.show({
                title: 'Atenção',
                icon: Ext.Msg.WARNING,
                buttons: Ext.Msg.OK,
                msg: 'Primeiro selecione um documento'
            });
        }
    },

    getToolbar: function(cfg) {
        if(!this._toolbar) {
            judicial.tac.DocumentGrid.superclass.getToolbar.call(this, cfg);
            this._toolbar.remove(10);
            this._toolbar.remove(9);
            this._toolbar.remove(8);
            this._toolbar.remove(7);
            this._toolbar.remove(6);
            this._toolbar.remove(5);
            this._toolbar.remove(4);
        }
        this._toolbar.add(
            {
                text: 'Download',
                scope: this,
                handler: this.downloadItem,
                iconCls: 'icon-diarias icon-diarias icon-move-down'
            },
            {
                text: 'Validar',
                scope: this,
                icon: '/' + global.Context + '/static/rh/images/decisao.png',
                menu:[
                   {
                        text: 'Cumprido',
                        scope: this,
                        icon: '/' + global.Context + '/static/rh/images/autorizado.png',
                        handler: function(grid, row, col)
                        {
                            this.actionAccept(1);
                        }
                    },
                    {
                        text: 'Não Cumprido',
                        scope: this,
                        icon: '/' + global.Context + '/static/rh/images/nao_autorizado.png',
                        handler: function(grid, row, col)
                        {
                            this.actionAccept(2);
                        }
                    },
                ]
            }
        );

        return this._toolbar;
    },

    downloadItem: function() {
        open(this.getSelectionModel().getSelected().get('permalink'), "_self");
    },

    constructor: function(cfg) {
        cfg = (cfg ? cfg : {});

        Ext.applyIf(cfg, {
            columnAction: false,
        });

        judicial.tac.DocumentGrid.superclass.constructor.call(this, cfg);
    }
});

core.RestfulGrid.register(
    'judicial.tac.DocumentRestful',
    'judicial.tac.DocumentGrid'
);
